      return res.status(400).send('Failed to verify SMTP connection configuration')
    }

    transporter.sendMail({
      from: Database.emailSettings.fromAddress,
      to: device.email,
      subject: "Here is your Ebook!",
      html: '<div dir="auto"></div>',
      attachments: [
